grant create on schema api,app_private to git_tutor_commands;
create function api.get_workload_report_page(p_from date,p_to date,p_tutor_cursor uuid default null,p_conversation_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();is_admin boolean:=app_private.has_role(actor,'admin');from_at timestamptz;to_at timestamptz;tutors jsonb:='[]';conversations jsonb:='[]';summary jsonb;begin
 if not is_admin and not app_private.has_role(actor,'customer_service')then raise exception'FORBIDDEN';end if;
 select period_start,period_end into from_at,to_at from finance_private.finance_report_range(p_from,p_to,now());if p_to-p_from>93 or p_limit is null or p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;
 if is_admin then
  with delivered as(select distinct occurrence_id,tutor_id,actual_start_at,actual_end_at from app_private.analytics_attendance(now())),
  occurrence_times as(select o.id,o.tutor_id,o.start_at,case when o.state<>'cancelled'and o.start_at>=from_at and o.start_at<to_at then extract(epoch from o.end_at-o.start_at)::bigint else 0 end scheduled_seconds,case when d.actual_start_at>=from_at and d.actual_start_at<to_at then extract(epoch from d.actual_end_at-d.actual_start_at)::bigint else 0 end delivered_seconds from app_private.occurrences o left join delivered d on d.occurrence_id=o.id where(o.start_at>=from_at and o.start_at<to_at)or(d.actual_start_at>=from_at and d.actual_start_at<to_at)),
  capacity as(select t.id,case when ar.id is null then null else coalesce((select sum(extract(epoch from((day::date+(i->>'end_local')::time)at time zone'Africa/Cairo')-((day::date+(i->>'start_local')::time)at time zone'Africa/Cairo')))from generate_series(p_from::timestamp,p_to::timestamp,interval'1 day')day left join app_private.availability_exceptions ex on ex.tutor_id=t.id and ex.local_date=day::date cross join lateral jsonb_array_elements(coalesce(ex.intervals,(select coalesce(jsonb_agg(w),'[]')from jsonb_array_elements(ar.weekly_intervals)w where(w->>'weekday')::integer=extract(isodow from day))))i),0)::bigint end seconds from app_private.tutors t left join app_private.availability_rules ar on ar.tutor_id=t.id)
  select coalesce(jsonb_agg(jsonb_build_object('tutor_id',t.id,'tutor_name',p.display_name,'scheduled_seconds',coalesce((select sum(o.scheduled_seconds)from occurrence_times o where o.tutor_id=t.id),0),'delivered_seconds',coalesce((select sum(o.delivered_seconds)from occurrence_times o where o.tutor_id=t.id),0),'available_seconds',cap.seconds,'capacity_state',case when cap.seconds is null then'unknown'else'configured'end,'occurrences',(select coalesce(jsonb_agg(jsonb_build_object('occurrence_id',o.id,'start_at',o.start_at,'scheduled_seconds',o.scheduled_seconds,'delivered_seconds',o.delivered_seconds)order by o.start_at,o.id),'[]')from occurrence_times o where o.tutor_id=t.id))order by t.id),'[]')into tutors from app_private.tutors t join app_private.accounts a on a.id=t.account_id join app_private.people p on p.id=a.person_id join capacity cap on cap.id=t.id;
 end if;
 with ownership as(select h.*,lead(h.created_at,1,now())over(partition by h.conversation_id order by h.created_at,h.id)ended_at from app_private.support_ownership_history h),
 response as(select c.id,first_incoming.created_at incoming_at,first_reply.created_at reply_at from app_private.conversations c left join lateral(select created_at from app_private.support_messages m where m.conversation_id=c.id and m.author='customer'order by m.created_at,m.sequence limit 1)first_incoming on true left join lateral(select created_at from app_private.support_messages m where m.conversation_id=c.id and m.author='staff'and m.created_at>=first_incoming.created_at and(is_admin or m.actor_account_id=actor)order by m.created_at,m.sequence limit 1)first_reply on true)
 select coalesce(jsonb_agg(jsonb_build_object('conversation_id',c.id,'channel',c.channel,'state',c.state,'owner_id',c.owner_account_id,'owner_name',p.display_name,'waiting_seconds',case when c.waiting_since is null or c.state='resolved'then null else greatest(0,floor(extract(epoch from now()-c.waiting_since)))end,'first_response_seconds',case when r.reply_at is null then null else greatest(0,floor(extract(epoch from r.reply_at-r.incoming_at)))end,'owned_seconds',(select coalesce(sum(greatest(0,floor(extract(epoch from least(h.ended_at,to_at,now())-greatest(h.created_at,from_at))))),0)from ownership h where h.conversation_id=c.id and h.new_owner_id is not null and(is_admin or h.new_owner_id=actor)),'ownership_changes',(select count(*)from ownership h where h.conversation_id=c.id and h.created_at>=from_at and h.created_at<to_at and(is_admin or h.new_owner_id=actor or h.previous_owner_id=actor)))order by c.id),'[]')into conversations from app_private.conversations c left join app_private.accounts a on a.id=c.owner_account_id left join app_private.people p on p.id=a.person_id left join response r on r.id=c.id where(c.created_at>=from_at and c.created_at<to_at or c.state in('waiting','assigned','escalated')or exists(select 1 from app_private.support_messages m where m.conversation_id=c.id and m.created_at>=from_at and m.created_at<to_at))and(is_admin or c.owner_account_id=actor);

 summary:=jsonb_build_object('scheduled_seconds',(select coalesce(sum((r->>'scheduled_seconds')::bigint),0)from jsonb_array_elements(tutors)r),'delivered_seconds',(select coalesce(sum((r->>'delivered_seconds')::bigint),0)from jsonb_array_elements(tutors)r),'open_conversations',(select count(*)from jsonb_array_elements(conversations)r where r->>'state'not in('resolved','bot')),'unassigned_conversations',(select count(*)from jsonb_array_elements(conversations)r where r->>'state'not in('resolved','bot')and r->>'owner_id'is null),'answered_conversations',(select count(*)from jsonb_array_elements(conversations)r where r->>'first_response_seconds'is not null),'total_response_seconds',(select coalesce(sum((r->>'first_response_seconds')::bigint),0)from jsonb_array_elements(conversations)r),'total_owned_seconds',(select coalesce(sum((r->>'owned_seconds')::bigint),0)from jsonb_array_elements(conversations)r));
 select coalesce(jsonb_agg(r order by r->>'tutor_id'),'[]')into tutors from(select value r from jsonb_array_elements(tutors)where p_tutor_cursor is null or(value->>'tutor_id')::uuid>p_tutor_cursor order by value->>'tutor_id'limit p_limit)x;
 select coalesce(jsonb_agg(r order by r->>'conversation_id'),'[]')into conversations from(select value r from jsonb_array_elements(conversations)where p_conversation_cursor is null or(value->>'conversation_id')::uuid>p_conversation_cursor order by value->>'conversation_id'limit p_limit)x;
 return jsonb_build_object('from',p_from,'to',p_to,'time_zone','Africa/Cairo','staffed_hours_state','unknown','staffed_response_seconds',null,'tutors',tutors,'conversations',conversations,'summary',summary,'next_cursor',null,'tutor_next_cursor',case when jsonb_array_length(tutors)=p_limit then tutors->-1->>'tutor_id'else null end,'conversation_next_cursor',case when jsonb_array_length(conversations)=p_limit then conversations->-1->>'conversation_id'else null end);
end$$;

create or replace function api.get_workload_report(p_from date,p_to date)returns jsonb language sql security definer set search_path='' as $$select api.get_workload_report_page(p_from,p_to,null,null,25)$$;
alter function api.get_workload_report_page(date,date,uuid,uuid,integer) owner to git_tutor_commands;
revoke all on function api.get_workload_report_page(date,date,uuid,uuid,integer) from public,anon,authenticated,service_role,git_tutor_worker;
grant execute on function api.get_workload_report_page(date,date,uuid,uuid,integer) to authenticated;
revoke create on schema api,app_private from git_tutor_commands;